    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if revision_priority == "sequence_first":
                rank = (sequence, event.get("revision", 0), pos)
            else:
                rank = (event.get("revision", 0), pos)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            base = net if tax_base == "discounted" else raw
            tax = rounded(base * event.get("tax_bp", 0), mode)
            total = net + tax
            if refunds and event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        order = sorted(names, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = []
        for name in names:
            choices.append([-1] + [row["version"] for row in packages[name]])

        best_vector = None
        best = None
        for values in product(*choices):
            versions = dict(zip(names, values))
            if any(versions[name] != -1 and
                   (versions[name] in blocked.get(name, []) or
                    (name in pins and versions[name] != pins[name]))
                   for name in names):
                continue
            valid = True
            for name, (low, high) in roots.items():
                if versions[name] == -1 or not low <= versions[name] <= high:
                    valid = False
                    break
            if not valid:
                continue

            rows = {}
            for name in names:
                if versions[name] != -1:
                    rows[name] = next(row for row in packages[name]
                                      if row["version"] == versions[name])
            edges = {name: [] for name in rows}
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = versions[target]
                    if version == -1 or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(rows):
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for child in edges.get(name, []):
                    if not visit(child):
                        return False
                state[name] = 2
                return True

            if not all(visit(name) for name in rows):
                continue
            vector = tuple(versions[name] for name in order)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: versions[name] for name in names if versions[name] != -1}

        return {"error": "unsatisfiable"} if best is None else {"versions": best}
    return solve


def _component_07():
    from itertools import combinations

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for chosen in combinations(jobs, k):
            ids = {job["id"] for job in chosen}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in chosen:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, change in sorted(events, key=lambda item: (item[0], item[1])):
                active += change
                if active > 2:
                    feasible = False
                    break
            if not feasible:
                continue
            value = sum(job["value"] for job in chosen)
            selected = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value, best_ids = value, selected
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, data["coupons"], initial_mask)
        start = data["start"]
        distances = {initial: start}
        queue = [(start, source, data["coupons"], initial_mask)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and time <= data["deadline"]:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], remaining)]
                if remaining:
                    durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, next_remaining in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_remaining, next_mask)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"], next_remaining, next_mask))
        return {"arrival": None}
    return solve


